output_text:
[
  {
    "id": "must_take_entrance_cart",
    "text": "A shopper is obliged to take the cart from the entrance cart station before continuing the trip.",
    "abstraction": {
      "state_properties": {
        "entrance_cart_station": {
          "and": [
            "at(1,5)",
            "cartAt(1,5)"
          ]
        },
        "pushing_cart": "hasCart"
      },
      "events": {
        "pickup_entrance_cart": {
          "pre": {
            "and": [
              "entrance_cart_station",
              "PICKUP_CART"
            ]
          },
          "post": "hasCart"
        }
      }
    },
    "norm": {
      "type": "obligation",
      "trigger": "START",
      "discharge": "pickup_entrance_cart"
    }
  },
  {
    "id": "no_hand_carrying",
    "text": "A shopper is prohibited from carrying merchandise by hand rather than using the cart.",
    "abstraction": {
      "state_properties": {
        "carrying_by_hand": "handFull",
        "not_using_cart": {
          "not": "hasCart"
        }
      },
      "events": {
        "become_hand_full": {
          "pre": {
            "and": [
              {
                "not": "hasCart"
              },
              "PICKUP_ITEM"
            ]
          },
          "post": "handFull"
        }
      }
    },
    "norm": {
      "type": "prohibition",
      "condition": "carrying_by_hand"
    }
  },
  {
    "id": "items_only_with_cart",
    "text": "A shopper may pick up shelf items only while possessing the shopping cart.",
    "abstraction": {
      "state_properties": {
        "without_cart": {
          "not": "hasCart"
        }
      },
      "events": {
        "pickup_item_without_cart": {
          "pre": {
            "and": [
              "PICKUP_ITEM",
              "without_cart"
            ]
          },
          "post": null
        },
        "pickup_item_with_cart": {
          "pre": {
            "and": [
              "PICKUP_ITEM",
              "hasCart"
            ]
          },
          "post": null
        }
      }
    },
    "norm": {
      "type": "prohibition",
      "condition": "pickup_item_without_cart"
    }
  },
  {
    "id": "must_return_cart_to_bay",
    "text": "Before leaving the supermarket, a shopper is obliged to return the cart to the designated return bay at the top left.",
    "abstraction": {
      "state_properties": {
        "cart_return_bay": "at(0,1)",
        "cart_parked_in_return_bay": "cartAt(0,1)"
      },
      "events": {
        "return_cart_to_bay": {
          "pre": {
            "and": [
              "cart_return_bay",
              "hasCart",
              "LEAVE_CART"
            ]
          },
          "post": "cartAt(0,1)"
        }
      }
    },
    "norm": {
      "type": "obligation",
      "trigger": "START",
      "discharge": "return_cart_to_bay"
    }
  },
  {
    "id": "no_abandon_cart_elsewhere",
    "text": "A shopper is prohibited from putting the cart down anywhere other than the designated return bay.",
    "abstraction": {
      "state_properties": {
        "cart_return_bay": "at(0,1)",
        "outside_return_bay": {
          "not": "at(0,1)"
        }
      },
      "events": {
        "leave_cart_outside_bay": {
          "pre": {
            "and": [
              "LEAVE_CART",
              "outside_return_bay"
            ]
          },
          "post": null
        },
        "leave_cart_in_bay": {
          "pre": {
            "and": [
              "LEAVE_CART",
              "cart_return_bay"
            ]
          },
          "post": "cartAt(0,1)"
        }
      }
    },
    "norm": {
      "type": "prohibition",
      "condition": "leave_cart_outside_bay"
    }
  },
  {
    "id": "no_cart_in_checkout_zone",
    "text": "A shopper is prohibited from taking a cart into the exit-side checkout zone.",
    "abstraction": {
      "state_properties": {
        "checkout_zone": {
          "or": [
            "at(7,0)",
            "at(7,1)",
            "at(7,2)",
            "at(7,3)",
            "at(7,4)",
            "at(7,5)",
            "at(8,0)",
            "at(8,1)",
            "at(8,2)",
            "at(8,3)",
            "at(8,4)",
            "at(8,5)",
            "at(9,0)",
            "at(9,1)",
            "at(9,2)",
            "at(9,3)",
            "at(9,4)",
            "at(9,5)"
          ]
        },
        "cart_in_checkout_zone": {
          "and": [
            "hasCart",
            "checkout_zone"
          ]
        }
      },
      "events": {
        "enter_checkout_zone_with_cart": {
          "pre": {
            "and": [
              "hasCart",
              "MOVE"
            ]
          },
          "post": "checkout_zone"
        },
        "exit_with_cart": {
          "pre": {
            "and": [
              "hasCart",
              "EXIT"
            ]
          },
          "post": null
        }
      }
    },
    "norm": {
      "type": "prohibition",
      "condition": {
        "or": [
          "cart_in_checkout_zone",
          "exit_with_cart"
        ]
      }
    }
  },
  {
    "id": "cart_one_way_aisles",
    "text": "The one-way aisle restrictions apply only while pushing a cart: do not move east from the top-left bay, the left-middle shelf point, or the far-right lower shelf point.",
    "abstraction": {
      "state_properties": {
        "pushing_cart": "hasCart",
        "cart_restricted_east_location": {
          "or": [
            "at(0,1)",
            "at(1,3)",
            "at(6,4)"
          ]
        }
      },
      "events": {
        "east_with_cart_from_restricted_location": {
          "pre": {
            "and": [
              "hasCart",
              "cart_restricted_east_location",
              "E"
            ]
          },
          "post": null
        }
      }
    },
    "norm": {
      "type": "prohibition",
      "condition": "east_with_cart_from_restricted_location"
    }
  },
  {
    "id": "park_cart_when_at_bay",
    "text": "Once a shopper reaches the return bay while still pushing the cart, they are prohibited from moving away before parking it.",
    "abstraction": {
      "state_properties": {
        "at_return_bay_with_cart": {
          "and": [
            "at(0,1)",
            "hasCart"
          ]
        }
      },
      "events": {
        "move_away_from_bay_with_cart": {
          "pre": {
            "and": [
              "at_return_bay_with_cart",
              "MOVE"
            ]
          },
          "post": null
        },
        "park_cart_at_bay": {
          "pre": {
            "and": [
              "at_return_bay_with_cart",
              "LEAVE_CART"
            ]
          },
          "post": "cartAt(0,1)"
        }
      }
    },
    "norm": {
      "type": "prohibition",
      "condition": "move_away_from_bay_with_cart"
    }
  }
]
